use serde::{Deserialize, Serialize};

/// A thinking block within a response message.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone)]
#[non_exhaustive]
pub struct ThinkingBlock {
    /// The text of Claude's thinking process for this block.
    pub thinking: String,

    /// A value used to verify that this block was generated by Claude when it is passed back to
    /// the API.
    pub signature: String,
}

/// A thinking block within a request message.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone)]
#[non_exhaustive]
pub struct ThinkingBlockParam {
    /// The `thinking` text of this block as returned by the API.
    pub thinking: String,

    /// The `signature` value of this block, exactly as returned by the API.
    pub signature: String,
}

/// A redacted thinking block within a response message.
///
/// Returned when the internal reasoning generated by Claude is flagged by Anthropic's safety
/// systems.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone)]
#[non_exhaustive]
pub struct RedactedThinkingBlock {
    /// The encrypted thinking content.
    pub data: String,
}

/// A redacted thinking block within a request message.
#[cfg_attr(test, derive(utoipa::ToSchema))]
#[derive(Serialize, Deserialize, Debug, Clone)]
#[non_exhaustive]
pub struct RedactedThinkingBlockParam {
    /// The `data` value of this block, exactly as returned by the API. Pass it back unchanged.
    pub data: String,
}

impl ThinkingBlock {
    /// Creates a new [`ThinkingBlock`] from the given thinking summary and signature.
    pub fn new(thinking: impl Into<String>, signature: impl Into<String>) -> Self {
        Self {
            thinking: thinking.into(),
            signature: signature.into(),
        }
    }
}

impl ThinkingBlockParam {
    /// Creates a new [`ThinkingBlockParam`] from the given thinking text and signature.
    pub fn new(thinking: impl Into<String>, signature: impl Into<String>) -> Self {
        Self {
            thinking: thinking.into(),
            signature: signature.into(),
        }
    }
}

impl RedactedThinkingBlock {
    /// Creates a new [`RedactedThinkingBlock`] from the given encrypted data.
    pub fn new(data: impl Into<String>) -> Self {
        Self { data: data.into() }
    }
}

impl RedactedThinkingBlockParam {
    /// Creates a new [`RedactedThinkingBlockParam`] from the given encrypted data.
    pub fn new(data: impl Into<String>) -> Self {
        Self { data: data.into() }
    }
}

impl From<ThinkingBlock> for ThinkingBlockParam {
    fn from(value: ThinkingBlock) -> Self {
        Self {
            thinking: value.thinking,
            signature: value.signature,
        }
    }
}

impl From<RedactedThinkingBlock> for RedactedThinkingBlockParam {
    fn from(value: RedactedThinkingBlock) -> Self {
        Self { data: value.data }
    }
}
